function align(T,object,row){
 object.updateMatrixWorld(true);const box=new T.Box3().setFromObject(object),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3());
 const source=row.source_bounds,oldSize=new T.Vector3(...source.max).sub(new T.Vector3(...source.min)),oldCenter=new T.Vector3(...source.max).add(new T.Vector3(...source.min)).multiplyScalar(.5);
 const scale=oldSize.x/size.x;object.scale.setScalar(scale);object.position.copy(oldCenter.sub(center.multiplyScalar(scale)));if(row.kind==='aa'||row.kind==='coast')object.position.y=source.min[1]-box.min.y*scale;object.updateMatrixWorld(true);return object;
}
function buildApproved(T,id,options={}){
 const row=catalog.find(r=>r.id===id);if(!row)throw new Error('Unknown redesigned gun '+id);
 const k=gunKit(T,options);
 switch(row.kind){
  case'pistol':pistol(T,k,false);break;case'desert_eagle':pistol(T,k,true);break;
  case'ar':ar(k);break;case'smg':smg(k);break;case'shotgun':shotgun(k,false);break;case'spas12':shotgun(k,true);break;
  case'sniper':sniper(k,false);break;case'msr':sniper(k,true);break;case'rpg':rpg(T,k);break;case'ak47':ak(k);break;case'mp5':mp5(k);break;
  case'vector':vector(k);break;case'p90':p90(T,k);break;case'famas':famas(k);break;case'aa12':aa12(k);break;case'm79':m79(k);break;case'aa':aa(T,k);break;case'coast':coast(T,k);break;
  default:throw new Error('Missing design '+row.kind);
 }
 const result=k.finish(row.title);return align(T,result,row);
}


