  const source=hq50GunTemplate(T,type);if(!source)return null;
  const cell=type==='pistol'||type==='desert_eagle'?.010:.016;
  if(!state.distanceMaterial){
    const material=new T.MeshStandardMaterial({vertexColors:true,roughness:1,metalness:1});
    material.name='HQ50 distant approved surface';
    // Preserve the source materials' PBR values in the single opaque draw.
    material.onBeforeCompile=shader=>{
      shader.vertexShader='attribute vec2 hqSurface; varying vec2 vHqSurface;\n'+shader.vertexShader;
      shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvHqSurface = hqSurface;');
      shader.fragmentShader='varying vec2 vHqSurface;\n'+shader.fragmentShader;
      shader.fragmentShader=shader.fragmentShader.replace('#include <roughnessmap_fragment>','#include <roughnessmap_fragment>\nroughnessFactor = vHqSurface.x;');
      shader.fragmentShader=shader.fragmentShader.replace('#include <metalnessmap_fragment>','#include <metalnessmap_fragment>\nmetalnessFactor = vHqSurface.y;');
    };
    material.customProgramCacheKey=()=> 'hq50-distance-surface-v1';
    state.distanceMaterial=material;
  }
