  prepare:(T,type)=>!!hq50DistanceGun(T,type),
  createGround:hq50CreateGround,
  layout:(T,type)=>Object.prototype.hasOwnProperty.call(HQ50_GUN_LAYOUTS,type)?HQ50_GUN_LAYOUTS[type]:null,
  opticMount:(T,type)=>HQ50_GUN_LAYOUTS[type]?.opticMount||null,
  stats:(T,type)=>{const model=hq50GunTemplate(T,type);return model?JSON.parse(JSON.stringify(model.userData.assetStats)):null;},
